    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        DBConnection db=new DBConnection();
        String name=txtName.getText();
        try{
            con=db.getConnectivity();
            String sql="SELECT course FROM student_register WHERE name=?";
            PreparedStatement psmt=con.prepareStatement(sql);
            psmt.setString(1,name);
            
            ResultSet rs=psmt.executeQuery();
            if(rs.next()){
                txtCourse.setText(rs.getString("course"));
            }else{
                JOptionPane.showMessageDialog(null, "No record found");
                txtCourse.setText("");
            }           
           
        }catch(Exception ex){
            ex.printStackTrace();
        }
    }//GEN-LAST:event_jButton1ActionPerformed

    private void btnCalActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnCalActionPerformed
        try{DBConnection db=new DBConnection();
            String name=txtName.getText();
            String courseName=txtCourse.getText();
            double paperMarks = Double.parseDouble(txtPaper.getText());
            double courseWork = Double.parseDouble(txtCw.getText());

            double finalMark=(paperMarks + courseWork) / 2;
            txtFmark.setText(String.format("%.2f", finalMark));

            String grade;
            if(finalMark < 40){
                grade ="F";
            }else if(finalMark<50){
                grade ="S";
            }else if(finalMark<60){
                grade="C";
            }else if(finalMark<75){
                grade="B";
            }else{
                grade="A";
            }
            txtFgrade.setText(grade);

            con=db.getConnectivity();
            String sql = "INSERT INTO results(name,course,final_marks,final_grade) VALUES(?,?,?,?)";
            PreparedStatement psmt=con.prepareStatement(sql);
            psmt.setString(1, name);
            psmt.setString(2, courseName);
            psmt.setDouble(3, finalMark);
            psmt.setString(4, grade);

            int rows =psmt.executeUpdate();
            if(rows> 0){
                JOptionPane.showMessageDialog(null,"Results saved successfully!");
            }
        }catch(NumberFormatException ex){
            JOptionPane.showMessageDialog(null,"Please enter valid numbers!");
        }catch(SQLException ex){
            JOptionPane.showMessageDialog(null, "Database Error:"+ex.getMessage());
        }
    }//GEN-LAST:event_btnCalActionPerformed

